python3 << 'PYEOF'
import os, re

patterns = [
    (r'ghp_[A-Za-z0-9]{36}', 'GitHub PAT'),
    (r'rnd_[A-Za-z0-9]{30}', 'Render API key'),
    (r'AKIA[A-Z0-9]{16}', 'AWS Access Key'),
    (r'vck_[A-Za-z0-9]{40}', 'Vercel AI Gateway key'),
    (r'sbp_[A-Za-z0-9]{40}', 'Supabase access token'),
    (r'eyJ[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+', 'JWT/Service Role key'),
]

findings = []
exclude_dirs = {'.git', 'node_modules'}
exclude_exts = {'.png', '.jpg', '.jpeg', '.gif', '.webp', '.ico', '.apk', '.aab', '.ipa', '.app', '.bin', '.woff', '.woff2', '.ttf'}

for root, dirs, files in os.walk('.'):
    dirs[:] = [d for d in dirs if d not in exclude_dirs]
    for f in files:
        ext = os.path.splitext(f)[1].lower()
        if ext in exclude_exts:
            continue
        filepath = os.path.join(root, f)
        try:
            with open(filepath, 'r', errors='ignore') as fh:
                content = fh.read()
                for pattern, name in patterns:
                    matches = re.findall(pattern, content)
                    if matches:
                        for m in matches:
                            # Mask the secret
                            masked = m[:6] + '...' + m[-4:] if len(m) > 10 else m[:3] + '...'
                            findings.append({
                                'file': filepath[2:],  # remove ./
                                'secretType': name,
                                'maskedValue': masked
                            })
        except:
            pass

if findings:
    print(f"FOUND {len(findings)} potential secrets:")
    for f in findings:
        print(f"  {f['secretType']:25} {f['maskedValue']:20} {f['file']}")
else:
    print("NO SECRETS FOUND in source files")

# Also check for .env files
env_files = []
for root, dirs, files in os.walk('.'):
    dirs[:] = [d for d in dirs if d not in exclude_dirs]
    for f in files:
        if f == '.env' or (f.startswith('.env') and f != '.env.example'):
            env_files.append(os.path.join(root, f))

if env_files:
    print(f"\nFOUND {len(env_files)} .env files:")
    for f in env_files:
        print(f"  {f}")
else:
    print("\nNo .env files found (good)")

# Write report
import json
report = {
    "phase": "PHASE 5 — SECRET SCAN",
    "findings": findings,
    "envFiles": env_files,
    "totalSecrets": len(findings),
    "totalEnvFiles": len(env_files)
}
os.makedirs("recovery", exist_ok=True)
with open("recovery/secret-scan-report.json", "w") as f:
    json.dump(report, f, indent=2)
print(f"\nReport saved to recovery/secret-scan-report.json")
PYEOF

